# ---------------------------------------------------------------------------
# Cross-log atomic transactions
#
# Four entry points only: :func:`tx_begin_metrics`,
# :func:`tx_commit_metrics`, :func:`tx_rollback_metrics` and
# :func:`tx_read_metrics`.  A transaction appends one batch of metric
# records to each of several independent logs so that commit makes every
# participating log gain its whole batch and rollback makes none of them
# gain anything.  Old segment sets need no migration and keep their
# format; transaction state lives entirely in new sidecars.
#
# The transaction identifier is an exact decimal integer.  Its
# coordinator record is one JSON document in a process-shared registry
# directory under the system temporary directory
# (``<tmp>/weighted_batcher_tx/<id>.json``); it binds the integer-id,
# the status, the participating logs (absolute paths, canonical order),
# one list of canonical record lines per log, and that log's exact
# decimal write serial.  ``<id>.lock`` is a never-renamed flock anchor
# serialising commit and rollback across processes.
#
# Each participating log carries two private, non-numeric sidecars
# (invisible to ``_segment_numbers`` and to every established read):
# ``path.tx`` is a JSON registry of the transactions currently prepared
# against the log, and ``path.txstage.<id>`` is that transaction's
# staging file holding the exact bytes -- canonical lines and their one
# terminating newline -- that commit appends whole.
#
# Crash protocol, strictly ordered:
#
# * begin/prepare: each log is locked (canonical path order, one at a
#   time), its own half-finished compaction/prune/snapshot settled, its
#   batch staged byte for byte and fsynced, and a ``prepared`` sidecar
#   entry atomically published.  No live-log byte changes, so an open
#   transaction neither blocks nor disturbs ordinary operation.
# * commit: every participating log is locked in canonical order and
#   settled, its exact write serial (the settled record total, pruned
#   records included) is read, and only then is the coordinator record
#   atomically flipped to ``committed`` -- the single commit point; each
#   log then appends its staged bytes as ONE whole newline-terminated
#   write, publishes an ``applied`` sidecar marker (after the fsync) and
#   removes the staging file.  A crash in the append leaves a torn
#   prefix no read acknowledges; the next write truncates and rewrites
#   the batch whole.
# * rollback: the coordinator record is flipped to ``rolled_back``; each
#   log discards any matching torn prefix, removes staging and sidecar
#   entry.  Nothing readable ever existed before the commit point.
#
# Transaction residue is settled from :func:`_finish_pending` after an
# unfinished compaction or prune and before the audit chain catches up,
# fixing its order against those leftovers deterministically.
# ---------------------------------------------------------------------------

_TX_VERSION = 1
_TX_STATUS_PREPARED = "prepared"
_TX_STATUS_COMMITTED = "committed"
_TX_STATUS_ROLLED_BACK = "rolled_back"
_TX_STATUS_APPLIED = "applied"
_TX_REGISTRY_DIRNAME = "weighted_batcher_tx"
_TX_SIDECAR_SUFFIX = ".tx"
_TX_SIDECAR_TMP_SUFFIX = ".tx.tmp"
_TX_STAGE_SUFFIX = ".txstage."
_TX_STAGE_TMP_SUFFIX = ".txstage.tmp."

# fcntl flock is per open file description: even within one process a
# second open of a locked inode is denied while another thread holds it.
# These reentrant per-path guards order same-process threads before the
# flock is touched, so interleaving neither self-deadlocks nor reports a
# spurious locking failure.
_tx_guard_table_lock = threading.Lock()
_tx_path_guards = {}
_tx_path_guard_refs = {}
_tx_coord_locks = {}
_tx_coord_lock_refs = {}


class _TxGuard:
    """Reentrant in-process mutual exclusion keyed by one string."""

    def __init__(self, table, refs, key):
        self._table = table
        self._refs = refs
        self._key = key
        with _tx_guard_table_lock:
            guard = table.get(key)
            if guard is None:
                guard = threading.RLock()
                table[key] = guard
                refs[key] = 0
            self._guard = guard
            refs[key] += 1

    def __enter__(self):
        self._guard.acquire()
        return self

    def __exit__(self, exc_type, exc, tb):
        self._guard.release()
        with _tx_guard_table_lock:
            self._refs[self._key] -= 1
            if self._refs[self._key] == 0:
                del self._table[self._key]
                del self._refs[self._key]
        return False


def _tx_log_guard(path):
    return _TxGuard(
        _tx_path_guards, _tx_path_guard_refs, os.path.abspath(path)
    )


def _tx_registry_dir():
    return os.path.join(tempfile.gettempdir(), _TX_REGISTRY_DIRNAME)


def _tx_record_path(txid):
    return os.path.join(_tx_registry_dir(), f"{txid}.json")


def _tx_lock_path(txid):
    return os.path.join(_tx_registry_dir(), f"{txid}.lock")


def _tx_stage_path(path, txid):
    return f"{path}{_TX_STAGE_SUFFIX}{txid}"


def _tx_sidecar_path(path):
    return path + _TX_SIDECAR_SUFFIX


def _tx_check_identifier(txid):
    """Validate the public type of a transaction identifier.

    Booleans do not count as integers (:class:`TypeError`); a negative
    identifier cannot name an issued transaction (:class:`ValueError`).
    """
    if isinstance(txid, bool) or not isinstance(txid, int):
        raise TypeError(
            f"transaction id must be an integer, got {type(txid).__name__}"
        )
    if txid < 0:
        raise ValueError(f"forged transaction id: {txid}")


def _tx_publish_json(tmp, target, payload):
    """Stage ``payload``, fsync it and atomically rename it into place."""
    try:
        out = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o666)
        try:
            _write_bytes(out, payload)
            os.fsync(out)
        finally:
            os.close(out)
        os.replace(tmp, target)
    except BaseException:
        _unlink_if_exists(tmp)
        raise


def _tx_read_json(path, what):
    """Read and decode a JSON transaction document at ``path``."""
    fd = os.open(path, os.O_RDONLY)
    try:
        raw = b""
        while True:
            chunk = os.read(fd, _READ_CHUNK)
            if not chunk:
                break
            raw += chunk
    finally:
        os.close(fd)
    try:
        return json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError) as exc:
        raise ValueError(f"corrupt {what} {path!r}: {exc}") from exc


def _tx_entry_valid(entry):
    """Structurally validate one per-log sidecar entry."""
    if not isinstance(entry, dict):
        return False
    status = entry.get("s")
    if status not in (
        _TX_STATUS_PREPARED, _TX_STATUS_APPLIED
    ):
        return False
    lines = entry.get("r")
    if not isinstance(lines, list) or not all(
        isinstance(line, str) for line in lines
    ):
        return False
    if set(entry) != {"s", "r"}:
        return False
    return True


def _tx_read_sidecar(path):
    """Read the per-log transaction registry; a missing one is empty.

    Anything present but not one JSON object mapping decimal transaction
    ids to well-formed entries is corrupt state and raises
    :class:`ValueError`.
    """
    target = _tx_sidecar_path(path)
    try:
        registry = _tx_read_json(target, "transaction registry")
    except FileNotFoundError:
        return {}
    if not isinstance(registry, dict):
        raise ValueError(
            f"corrupt transaction registry {target!r}: state must be a "
            f"JSON object"
        )
    for txid_text, entry in registry.items():
        if not (txid_text.isascii() and txid_text.isdigit()):
            raise ValueError(
                f"corrupt transaction registry {target!r}: bad transaction id"
            )
        if not _tx_entry_valid(entry):
            raise ValueError(
                f"corrupt transaction registry {target!r}: bad entry for "
                f"transaction {txid_text}"
            )
    return registry


def _tx_write_sidecar(path, registry):
    """Atomically publish the per-log transaction registry and fsync it."""
    payload = json.dumps(registry, separators=(",", ":")).encode("utf-8")
    _tx_publish_json(
        path + _TX_SIDECAR_TMP_SUFFIX, _tx_sidecar_path(path), payload
    )


def _tx_read_coordinator(txid):
    """Read a coordinator record; ``None`` when no record exists.

    Any present document that is not exactly one well-formed coordinator
    record is corrupt transaction state and raises :class:`ValueError`.
    """
    target = _tx_record_path(txid)
    try:
        record = _tx_read_json(target, "transaction record")
    except FileNotFoundError:
        return None
    if not isinstance(record, dict) or set(record) != {
        "v", "id", "s", "logs", "records", "serials"
    }:
        raise ValueError(
            f"corrupt transaction record {target!r}: unexpected fields"
        )
    if record["v"] != _TX_VERSION:
        raise ValueError(
            f"corrupt transaction record {target!r}: bad version"
        )
    if (
        isinstance(record["id"], bool)
        or not isinstance(record["id"], int)
        or record["id"] != txid
    ):
        raise ValueError(
            f"corrupt transaction record {target!r}: id mismatch"
        )
    if record["s"] not in (
        _TX_STATUS_PREPARED,
        _TX_STATUS_COMMITTED,
        _TX_STATUS_ROLLED_BACK,
    ):
        raise ValueError(
            f"corrupt transaction record {target!r}: bad status"
        )
    logs = record["logs"]
    records = record["records"]
    serials = record["serials"]
    if (
        not isinstance(logs, list)
        or not all(isinstance(one, str) for one in logs)
        or not isinstance(records, list)
        or len(records) != len(logs)
        or not isinstance(serials, list)
        or len(serials) != len(logs)
    ):
        raise ValueError(
            f"corrupt transaction record {target!r}: bad log set"
        )
    for lines, serial in zip(records, serials):
        if not isinstance(lines, list) or not all(
            isinstance(line, str) for line in lines
        ):
            raise ValueError(
                f"corrupt transaction record {target!r}: bad records"
            )
        if isinstance(serial, bool) or not isinstance(serial, int) or serial < 0:
            raise ValueError(
                f"corrupt transaction record {target!r}: bad write serial"
            )
    return record


def _tx_write_coordinator(record):
    """Atomically publish a coordinator record, creating the registry dir."""
    directory = _tx_registry_dir()
    os.makedirs(directory, exist_ok=True)
    txid = record["id"]
    payload = json.dumps(record, separators=(",", ":")).encode("utf-8")
    _tx_publish_json(
        os.path.join(directory, f"{txid}.json.tmp"),
        _tx_record_path(txid),
        payload,
    )


def _tx_batch_payload(lines):
    """Exact bytes appended for one log's lines, with one final newline."""
    if not lines:
        return b""
    return b"".join(line.encode("utf-8") for line in lines) + b"\n"


def _tx_write_stage(path, txid, payload):
    """Stage one log's whole batch, fsynced and atomically named."""
    if not payload:
        return
    _tx_publish_json(
        f"{path}{_TX_STAGE_TMP_SUFFIX}{txid}",
        _tx_stage_path(path, txid),
        payload,
    )


def _tx_remove_stage(path, txid):
    _unlink_if_exists(_tx_stage_path(path, txid))
    _unlink_if_exists(f"{path}{_TX_STAGE_TMP_SUFFIX}{txid}")


def _tx_record_total(path):
    """The settled record total, pruned records included."""
    pruned = _read_prune_state(path)[0]
    surviving = 0
    for member in _segment_members(path):
        for _ in _iter_raw_records(member):
            surviving += 1
    return pruned + surviving


def _tx_live_tail(path):
    """Return ``(cut, suffix)`` for the live log's final unterminated region.

    A transaction append is the only writer that can leave such a region
    here; an ordinary completed append always ends in a newline.
    """
    try:
        size = os.path.getsize(path)
    except FileNotFoundError:
        return 0, b""
    fd = os.open(path, os.O_RDONLY)
    try:
        data = b""
        while True:
            chunk = os.read(fd, _READ_CHUNK)
            if not chunk:
                break
            data += chunk
    finally:
        os.close(fd)
    newline = data.rfind(b"\n")
    if newline < 0:
        return 0, data
    return newline + 1, data[newline + 1:]


def _tx_truncate(path, cut):
    fd = os.open(path, os.O_WRONLY)
    try:
        os.ftruncate(fd, cut)
        os.fsync(fd)
    finally:
        os.close(fd)


def _tx_append_whole(path, payload):
    """Append one whole newline-terminated batch in a single write."""
    out = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o666)
    try:
        _write_bytes(out, payload)
        os.fsync(out)
    finally:
        os.close(out)


def _tx_batch_already_tail(path, payload):
    """True when the live log ends exactly on the whole batch bytes."""
    try:
        size = os.path.getsize(path)
    except FileNotFoundError:
        return False
    if size < len(payload):
        return False
    fd = os.open(path, os.O_RDONLY)
    try:
        os.lseek(fd, size - len(payload), os.SEEK_SET)
        tail = b""
        while len(tail) < len(payload):
            chunk = os.read(fd, len(payload) - len(tail))
            if not chunk:
                break
            tail += chunk
    finally:
        os.close(fd)
    return tail == payload


def _tx_force_committed(path, txid, lines):
    """Finish a post-commit-point log under the caller's write lock.

    Returns True when the batch is present in the live log afterwards.
    A crash mid-append leaves a prefix torn tail; it is truncated and the
    whole batch is rewritten in one write, so no record ever joins
    recovery half written.
    """
    payload = _tx_batch_payload(lines)
    if not payload:
        return True
    if _tx_batch_already_tail(path, payload):
        return True
    cut, suffix = _tx_live_tail(path)
    if suffix and payload.startswith(suffix):
        _tx_truncate(path, cut)
    _tx_append_whole(path, payload)
    return True


def _tx_discard(path, txid, lines):
    """Remove a never-committed transaction's residue under the write lock.

    A commit point that never happened can only have left a staging file
    and a sidecar entry; an append that crashed is impossible without the
    committed record, but a prefix torn tail matching the batch is
    truncated defensively.
    """
    payload = _tx_batch_payload(lines)
    if payload:
        cut, suffix = _tx_live_tail(path)
        if suffix and payload.startswith(suffix):
            _tx_truncate(path, cut)
    _tx_remove_stage(path, txid)


def _tx_settle_log(path):
    """Resolve every transaction sidecar entry of one log.

    Called with the live-log lock held from :func:`_finish_pending`,
    after an unfinished compaction or prune is settled and before the
    audit chain is caught up, so transaction residue has one fixed place
    in the recovery order.  The coordinator record is the authority:

    * no record -- a begin crashed before publishing; residue discarded;
    * ``prepared`` -- still open; left exactly as staged;
    * ``rolled_back`` -- residue discarded and the entry removed;
    * ``committed`` -- the batch is forced to completion; an ``applied``
      marker only needs its staging file and entry cleaned up.
    """
    registry = _tx_read_sidecar(path)
    if not registry:
        return
    changed = False
    for txid_text, entry in list(registry.items()):
        txid = int(txid_text)
        lines = entry["r"]
        record = _tx_read_coordinator(txid)
        if record is None or record["s"] == _TX_STATUS_ROLLED_BACK:
            _tx_discard(path, txid, lines)
            del registry[txid_text]
            changed = True
        elif record["s"] == _TX_STATUS_COMMITTED:
            if entry["s"] != _TX_STATUS_APPLIED:
                _tx_force_committed(path, txid, lines)
            _tx_remove_stage(path, txid)
            del registry[txid_text]
            changed = True
        # Still prepared: untouched.
    if changed:
        _tx_write_sidecar(path, registry)


def _tx_validate_inputs(logs, records):
    """Validate the shapes and render every record to a canonical line."""
    if isinstance(logs, str) or not isinstance(logs, (list, tuple)):
        raise TypeError(
            f"logs must be a sequence of paths, got {type(logs).__name__}"
        )
    if isinstance(records, str) or not isinstance(records, (list, tuple)):
        raise TypeError(
            f"records must be a sequence of record batches, got "
            f"{type(records).__name__}"
        )
    if len(logs) != len(records):
        raise ValueError(
            f"log and record batch counts differ: {len(logs)} log(s) but "
            f"{len(records)} batch(es)"
        )
    for path in logs:
        if not isinstance(path, str):
            raise OSError(
                f"log path must be a string, got {type(path).__name__}"
            )
    groups = []
    payloads = []
    for batch in records:
        if isinstance(batch, str) or not isinstance(batch, (list, tuple)):
            raise TypeError(
                f"each record batch must be a list of metric mappings, got "
                f"{type(batch).__name__}"
            )
        lines = []
        for metrics in batch:
            if not isinstance(metrics, dict):
                raise TypeError(
                    f"each transaction record must be a metrics mapping, "
                    f"got {type(metrics).__name__}"
                )
            # render_metrics enforces string keys, int/float values
            # (booleans rejected), no NaN/Infinity, exact big integers,
            # -0.0 and insertion key order; strip its newline.
            lines.append(render_metrics(metrics)[:-1])
        groups.append(lines)
        payloads.append(_tx_batch_payload(lines))
    absolute = [os.path.abspath(path) for path in logs]
    if len(set(absolute)) != len(absolute):
        raise ValueError("a participating log path is repeated")
    return groups, payloads, absolute


def _tx_prepare_one(path, txid, lines, payload):
    """Stage one log's batch and publish its ``prepared`` sidecar entry."""
    with _tx_log_guard(path):
        fd = _mutation_lock(path, create=False)
        try:
            _finish_pending(path)
            fd = _relock_after_settle(fd, path, create=False)
            serial = _tx_record_total(path)
            _tx_write_stage(path, txid, payload)
            registry = _tx_read_sidecar(path)
            registry[str(txid)] = {
                "s": _TX_STATUS_PREPARED, "r": lines
            }
            _tx_write_sidecar(path, registry)
            return serial
        finally:
            if fd is not None:
                os.close(fd)


def _tx_discard_prepare(path, txid):
    """Undo one preparation (used when a later prepare fails)."""
    with _tx_log_guard(path):
        fd = _mutation_lock(path, create=False)
        try:
            _finish_pending(path)
            registry = _tx_read_sidecar(path)
            entry = registry.pop(str(txid), None)
            if entry is not None:
                _tx_write_sidecar(path, registry)
            _tx_remove_stage(path, txid)
        finally:
            if fd is not None:
                os.close(fd)


def tx_begin_metrics(logs, records):
    """Begin an atomic write over several logs and return its integer id.

    ``logs`` is the sequence of participating log paths and ``records``
    the matching per-log batches -- one list of metric mappings per log,
    in the exact order the records must appear.  The two sequences have
    the same length and no log path may repeat.  Records obey the
    established metric-line rules exactly: they are rendered
    canonically, so oversized integer counters stay exact decimal
    integers, ``-0.0`` is preserved and key order follows each mapping.
    The returned identifier and its coordinator record persist the
    integer-id, the participating log set and every record's exact
    decimal write serial.

    Preparation writes no live-log byte: each batch lands in that log's
    private staging file and a private sidecar entry, both invisible to
    every established read, so concurrent appends, rotations,
    compactions and prunes proceed while the transaction stays open.
    Logs are locked in canonical path order one at a time -- an acyclic
    graph for any two overlapping transactions -- and every input is
    validated and every log staged before the identifier exists, so a
    failure discards all partial preparations and leaves not one
    readable record behind.

    Raises:
        TypeError: ``logs`` or ``records`` is not a sequence, a record is
            not a mapping, a metric key is not a string or a metric value
            is not an int or float (booleans do not count).
        ValueError: the lengths differ, a path repeats, or a metric value
            is NaN or Infinity.
        FileNotFoundError: a participating log does not exist.
        IsADirectoryError: a participating path is a directory.
        OSError: a path is not a string, or locking or writing staging
            state fails; nothing readable is left behind.
    """
    groups, payloads, absolute = _tx_validate_inputs(logs, records)
    paths = list(logs)
    for path in paths:
        if os.path.isdir(path):
            raise IsADirectoryError(f"log path is a directory: {path!r}")
    for path in paths:
        if not os.path.exists(path):
            raise FileNotFoundError(f"metrics log does not exist: {path!r}")

    order = sorted(range(len(paths)), key=lambda index: absolute[index])

    while True:
        txid = int.from_bytes(os.urandom(8), "big")
        if txid and not os.path.exists(_tx_record_path(txid)):
            break

    prepared = []
    try:
        serials = [0] * len(paths)
        for index in order:
            serials[index] = _tx_prepare_one(
                paths[index], txid, groups[index], payloads[index]
            )
            prepared.append(index)
        record = {
            "v": _TX_VERSION,
            "id": txid,
            "s": _TX_STATUS_PREPARED,
            "logs": [absolute[index] for index in order],
            "records": [groups[index] for index in order],
            "serials": [serials[index] for index in order],
        }
        _tx_write_coordinator(record)
    except BaseException:
        # The commit point was never reached; undo every preparation.
        for index in prepared:
            try:
                _tx_discard_prepare(paths[index], txid)
            except OSError:
                pass
        raise
    return txid


def _tx_locked_logs(record):
    """Acquire every participating log's guards and locks, canonical order.

    Returns a list of ``(abspath, guard, fd)`` in acquisition order; the
    caller releases in reverse.  Canonical order (the logs are already
    stored sorted) keeps the combined in-process/flock graph acyclic for
    any two transactions whose log groups overlap.
    """
    held = []
    try:
        for abspath in record["logs"]:
            guard = _tx_log_guard(abspath)
            guard.__enter__()
            held.append((abspath, guard, None))
            fd = _mutation_lock(abspath, create=False)
            _finish_pending(abspath)
            fd = _relock_after_settle(fd, abspath, create=False)
            held[-1] = (abspath, guard, fd)
        return held
    except BaseException:
        for abspath, guard, fd in reversed(held):
            if fd is not None:
                try:
                    os.close(fd)
                except OSError:
                    pass
            guard.__exit__(None, None, None)
        raise


def _tx_release_locked(held):
    for abspath, guard, fd in reversed(held):
        if fd is not None:
            os.close(fd)
        guard.__exit__(None, None, None)


def tx_commit_metrics(txid):
    """Atomically commit prepared transaction ``txid``.

    Every participating log is locked in canonical order and settled, and
    its exact write serial -- the settled record total, pruned records
    included -- is read while its lock is held.  Only then is the
    coordinator record atomically published as ``committed`` with those
    serials: the single commit point.  Each log then appends its staged
    bytes as one whole newline-terminated write (so all its records
    become visible together), records an ``applied`` marker after the
    fsync and removes the staging file, all with the locks still held, so
    no ordinary append can interleave.  Before the commit point no log
    holds a batch record; after it every log holds the whole batch.

    A crash after the commit point leaves deterministic residue: a torn
    prefix no read acknowledges is truncated and the batch is rewritten
    whole by the next write on the log (which settles transaction residue
    first), and a retried commit finishes whatever remains.  The same
    identifier can never commit twice, take effect on only some logs, or
    commit after a rollback.

    Raises:
        TypeError: ``txid`` is not an integer (booleans do not count).
        ValueError: ``txid`` is negative, forged, was already committed,
            or was rolled back; or the transaction state is corrupt.
        FileNotFoundError: the coordinator record or a participating log
            is missing.
        IsADirectoryError: a participating path is a directory.
        OSError: locking or writing fails.
    """
    _tx_check_identifier(txid)
    with _TxGuard(_tx_coord_locks, _tx_coord_lock_refs, _tx_lock_path(txid)):
        if fcntl is not None:
            lock_fd = os.open(_tx_lock_path(txid), os.O_RDWR | os.O_CREAT, 0o666)
            try:
                fcntl.flock(lock_fd, fcntl.LOCK_EX)
            except OSError:
                os.close(lock_fd)
                raise
        else:
            lock_fd = None
        try:
            record = _tx_read_coordinator(txid)
            if record is None:
                raise ValueError(
                    f"forged or finished transaction id: {txid}"
                )
            if record["s"] == _TX_STATUS_COMMITTED:
                raise ValueError(
                    f"transaction {txid} was already committed"
                )
            if record["s"] == _TX_STATUS_ROLLED_BACK:
                raise ValueError(
                    f"transaction {txid} was already rolled back"
                )
            held = _tx_locked_logs(record)
            try:
                serials = []
                for abspath, _guard, _fd in held:
                    entry = _tx_read_sidecar(abspath).get(str(txid))
                    index = record["logs"].index(abspath)
                    lines = record["records"][index]
                    if entry is None or entry["r"] != lines:
                        raise ValueError(
                            f"corrupt transaction {txid} state at "
                            f"{abspath!r}: prepared records do not match "
                            f"the coordinator record"
                        )
                    serials.append(_tx_record_total(abspath))
                # The commit point: one atomic publication carrying the
                # exact serials read under every log's lock.
                record["serials"] = serials
                record["s"] = _TX_STATUS_COMMITTED
                _tx_write_coordinator(record)
                for abspath, _guard, _fd in held:
                    index = record["logs"].index(abspath)
                    lines = record["records"][index]
                    payload = _tx_batch_payload(lines)
                    if payload:
                        _tx_append_whole(abspath, payload)
                    registry = _tx_read_sidecar(abspath)
                    registry[str(txid)] = {
                        "s": _TX_STATUS_APPLIED, "r": lines
                    }
                    _tx_write_sidecar(abspath, registry)
                    _tx_remove_stage(abspath, txid)
                    registry = _tx_read_sidecar(abspath)
                    registry.pop(str(txid), None)
                    _tx_write_sidecar(abspath, registry)
                    _sync_audit_for_write(abspath)
            finally:
                _tx_release_locked(held)
        finally:
            if lock_fd is not None:
                os.close(lock_fd)


def tx_rollback_metrics(txid):
    """Roll prepared transaction ``txid`` back.

    The coordinator record is atomically published as ``rolled_back`` and
    every participating log then discards any matching torn prefix,
    removes its staging file and drops its sidecar entry under the
    live-log lock after the log's other pending work is settled.  Before
    the commit point no readable record existed, so rollback removes no
    record; repeating a finished rollback is a no-op, while committing a
    rolled-back identifier remains a :class:`ValueError`.

    Raises:
        TypeError: ``txid`` is not an integer (booleans do not count).
        ValueError: ``txid`` is negative, forged, or was already
            committed.
        FileNotFoundError: a participating log no longer exists.
        IsADirectoryError: a participating path is a directory.
        OSError: locking or writing fails.
    """
    _tx_check_identifier(txid)
    with _TxGuard(_tx_coord_locks, _tx_coord_lock_refs, _tx_lock_path(txid)):
        if fcntl is not None:
            lock_fd = os.open(_tx_lock_path(txid), os.O_RDWR | os.O_CREAT, 0o666)
            try:
                fcntl.flock(lock_fd, fcntl.LOCK_EX)
            except OSError:
                os.close(lock_fd)
                raise
        else:
            lock_fd = None
        try:
            record = _tx_read_coordinator(txid)
            if record is None:
                raise ValueError(
                    f"forged or finished transaction id: {txid}"
                )
            if record["s"] == _TX_STATUS_COMMITTED:
                raise ValueError(
                    f"transaction {txid} was already committed"
                )
            if record["s"] == _TX_STATUS_ROLLED_BACK:
                return
            record["s"] = _TX_STATUS_ROLLED_BACK
            _tx_write_coordinator(record)
            for abspath, lines in zip(record["logs"], record["records"]):
                with _tx_log_guard(abspath):
                    fd = _mutation_lock(abspath, create=False)
                    try:
                        _finish_pending(abspath)
                        _tx_discard(abspath, txid, lines)
                        registry = _tx_read_sidecar(abspath)
                        registry.pop(str(txid), None)
                        _tx_write_sidecar(abspath, registry)
                    finally:
                        if fd is not None:
                            os.close(fd)
        finally:
            if lock_fd is not None:
                os.close(lock_fd)


def tx_read_metrics(path, txid):
    """Stream one log's records from transaction ``txid``'s point of view.

    The view is whole at every call:

    * an open ``prepared`` transaction reads the log's current records
      followed by its own staged batch in write order;
    * a committed transaction whose finalise has not finished reads the
      current records with the staged batch appended whole -- never a
      torn prefix -- so the post-commit view is never observed half done;
      once the batch has joined the log, the ordinary segment-set walk
      already contains it and it is not produced twice;
    * a rolled-back transaction reads without the batch;
    * the staged bytes come from the sidecar or coordinator record,
      never from the live log's torn tail.

    Reading takes no log lock and changes no state, so a same-process
    prepare, commit or rollback interleaved with it neither deadlocks
    nor reports a spurious locking failure.

    Raises:
        TypeError: ``txid`` is not an integer (booleans do not count).
        ValueError: ``txid`` is negative, forged, belongs to another
            transaction than this log, or the transaction state is
            corrupt; a bad record line is raised lazily while iterating.
        FileNotFoundError: neither the log nor any segment exists.
        IsADirectoryError: ``path`` is a directory.
        OSError: ``path`` is not a string.
    """
    if not isinstance(path, str):
        raise OSError(f"log path must be a string, got {type(path).__name__}")
    _tx_check_identifier(txid)
    if os.path.isdir(path):
        raise IsADirectoryError(f"log path is a directory: {path!r}")
    members, _pruned = _resolve_members(path)
    if not members:
        raise FileNotFoundError(f"no metrics log or segments at {path!r}")

    abspath = os.path.abspath(path)
    sidecar = _tx_read_sidecar(path).get(str(txid))
    record = _tx_read_coordinator(txid)
    if sidecar is None and record is None:
        raise ValueError(f"forged or foreign transaction id: {txid}")
    if sidecar is None and abspath not in record["logs"]:
        raise ValueError(
            f"transaction {txid} does not participate in log {path!r}"
        )

    lines = []
    if sidecar is not None:
        candidate = sidecar["r"]
    else:
        index = record["logs"].index(abspath)
        candidate = record["records"][index]
    if record is None:
        # A begin crashed before publishing: the sidecar is the only
        # evidence; its own view still contains the prepared batch.
        lines = candidate
    elif record["s"] == _TX_STATUS_PREPARED:
        lines = candidate
    elif record["s"] == _TX_STATUS_ROLLED_BACK:
        lines = []
    else:  # committed
        stage_exists = bool(candidate) and os.path.exists(
            _tx_stage_path(path, txid)
        )
        if sidecar is not None and sidecar["s"] == _TX_STATUS_APPLIED:
            lines = []
        elif stage_exists:
            payload = _tx_batch_payload(candidate)
            if payload and _tx_batch_already_tail(path, payload):
                # The append landed but cleanup had not finished; the
                # ordinary walk below already ends on the whole batch.
                lines = []
            else:
                lines = candidate
        else:
            lines = []

    def _generate():
        for member in members:
            yield from _parse_file(member, member)
        for line in lines:
            yield parse_metrics(line)

    return _generate()
